// Command summarizer reads GitLab activity over the last N days and writes
// Markdown reports generated by an LLM — one customer-facing, one team-facing
// — per project, plus cross-project rollups.
//
// A run covers every project the token can see that had activity in the
// window, unless a project opts out (no-summarize topic, .summaryignore) or
// --project / --discover-group / --discover-by-topic narrow the set.
// --max-projects bounds the total. Outputs land under a configurable
// directory; the run summary goes to stderr.
//
// Usage:
//
//	summarizer run --project group/subgroup/project
//	summarizer run --project group/subgroup/project --dry-run
//	summarizer --version
//	summarizer --help
//
// Env vars (do not store tokens in config files):
//
//	GITLAB_TOKEN       required for fetch
//	OPENAI_API_KEY     required when --provider openai (default) and baseURL is api.openai.com; optional otherwise
//	OPENAI_BASE_URL    overrides the OpenAI-compatible endpoint (Ollama, vLLM, LM Studio)
//	ANTHROPIC_API_KEY  required when --provider anthropic
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"slices"
	"strings"
	"syscall"
	"time"

	"github.com/inful/summarizer/internal/config"
	"github.com/inful/summarizer/internal/gitlab"
	"github.com/inful/summarizer/internal/llm"
	"github.com/inful/summarizer/internal/publisher"
	"github.com/inful/summarizer/internal/run"
	"github.com/inful/summarizer/internal/safety"
)

// Build-time variables, overridden via:
//
//	go build -ldflags "-X main.version=vX.Y.Z -X main.commit=$(git rev-parse HEAD) -X main.date=..."
//
// Default values are intentionally informational rather than empty
// so a developer running `go run` sees what they're running. Goreleaser
// injects the real values at release time (see .goreleaser.yaml).
var (
	version = "dev"
	commit  = "none"
	date    = "unknown"
)

func main() {
	if len(os.Args) < 2 {
		usage()
		os.Exit(2)
	}
	switch os.Args[1] {
	case "run":
		os.Exit(runCmd(os.Args[2:]))
	case "monthly":
		os.Exit(monthlyCmd(os.Args[2:]))
	case "version", "--version", "-v":
		fmt.Printf("summarizer %s (commit %s, %s)\n", version, commit, date)
		os.Exit(0)
	case "help", "--help", "-h":
		usage()
		os.Exit(0)
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n\n", os.Args[1])
		usage()
		os.Exit(2)
	}
}

// resolveLLM builds the LLM provider from the resolved config,
// falling back to the usual environment variables for keys. Returns a
// non-zero exit code and prints the reason on failure.
//
// Shared by `run` and `monthly` so the two can't drift on which env
// vars they read or how they treat a local OpenAI-compatible server.
func resolveLLM(cfg *config.Config, openaiKey, anthropicKey string) (llm.Provider, int) {
	switch cfg.Provider {
	case "openai":
		key := openaiKey
		if key == "" {
			key = os.Getenv("OPENAI_API_KEY")
		}
		// Local OpenAI-compatible servers (Ollama, vLLM, LM Studio, llama.cpp)
		// typically don't require auth. Treat an empty key as opt-in to
		// "no auth" when the baseURL points somewhere other than the
		// canonical api.openai.com. For api.openai.com we still require
		// a key — better to fail loud than to silently send empty bearer.
		if key == "" && llm.IsOpenAIHost(cfg.OpenAIBaseURL) {
			fmt.Fprintln(os.Stderr, "error: provider=openai but OPENAI_API_KEY is not set (or set --openai-base-url for a local server)")
			return nil, exitEnv
		}
		return llm.NewOpenAI(key, cfg.Model, cfg.OpenAIBaseURL), exitOK
	case "anthropic":
		key := anthropicKey
		if key == "" {
			key = os.Getenv("ANTHROPIC_API_KEY")
		}
		if key == "" {
			fmt.Fprintln(os.Stderr, "error: provider=anthropic but ANTHROPIC_API_KEY is not set")
			return nil, exitEnv
		}
		return llm.NewAnthropic(key, cfg.Model, ""), exitOK
	default:
		fmt.Fprintf(os.Stderr, "error: unknown provider %q\n", cfg.Provider)
		return nil, exitConfig
	}
}

// newGuard builds the prompt-injection guard for both `run` and
// `monthly`. Shared so the monthly path cannot silently end up
// unguarded while the config says safety.enabled: true.
func newGuard(cfg *config.Config, enabled bool, url, token string) (safety.Guard, int) {
	if !enabled && !cfg.Safety.Enabled {
		return safety.NoopGuard{}, exitOK
	}
	decisionURL := url
	if decisionURL == "" {
		decisionURL = cfg.Safety.DecisionURL
	}
	if decisionURL == "" {
		fmt.Fprintln(os.Stderr, "error: --safety-enabled but no decision URL (set --safety-url or config safety.decision_url)")
		return nil, exitConfig
	}
	tokenEnv := cfg.Safety.DecisionTokenEnv
	if tokenEnv == "" {
		tokenEnv = "SAFETY_DECISION_TOKEN"
	}
	if token == "" {
		token = os.Getenv(tokenEnv)
	}
	threshold := cfg.Safety.InjectionThreshold
	if threshold <= 0 {
		threshold = 0.7
	}
	return safety.NewDecide(decisionURL, token, threshold), exitOK
}

// newPublisher builds the publisher for both `run` and `monthly`.
//
// Shared so the two cannot drift: monthlyCmd was missing the
// publish.project check that runCmd has, so one misconfiguration gave
// two different — and in monthly's case much worse — errors.
func newPublisher(cfg *config.Config) (publisher.Publisher, int) {
	if !cfg.Publish.Enabled {
		return publisher.NewLocal(cfg.OutputDir), exitOK
	}
	tokenEnv := cfg.Publish.TokenEnv
	if tokenEnv == "" {
		tokenEnv = "GITLAB_REPORTS_TOKEN"
	}
	if os.Getenv(tokenEnv) == "" {
		fmt.Fprintf(os.Stderr, "error: publish.enabled=true but $%s is not set\n", tokenEnv)
		return nil, exitEnv
	}
	if cfg.Publish.Project == "" {
		fmt.Fprintln(os.Stderr, "error: publish.enabled=true but publish.project is empty")
		return nil, exitConfig
	}
	host := cfg.Publish.Host
	if host == "" {
		host = cfg.GitLabHost
	}
	return publisher.NewGitLab(
		host, os.Getenv(tokenEnv), cfg.Publish.Project,
		cfg.Publish.Prefix, cfg.Publish.DefaultBranch, cfg.Publish.SourceBranchPrefix,
	), exitOK
}

func usage() {
	fmt.Fprint(os.Stderr, `summarizer — GitLab project activity → two Markdown reports

Commands:
  run         Fetch activity, call LLM, write reports
  monthly     Roll up a month of published weekly rollups
  version     Print version and exit
  help        Print this message

Run 'summarizer run --help' for run flags.
Run 'summarizer monthly --help' for monthly flags.
`)
}

// exit codes — distinct branches in a cron script can react to each.
const (
	exitOK        = 0
	exitUsage     = 2
	exitConfig    = 3
	exitGitLab    = 4
	exitLLM       = 5
	exitWrite     = 6
	exitEnv       = 7
	exitInjection = 8
	exitUnknown   = 1
)

// runDeadline bounds one `summarizer run`. See the comment at the
// signal.NotifyContext call for why it exists and why it is set so far
// above a real run that it only fires on a stuck upstream.
const runDeadline = 6 * time.Hour

func runCmd(args []string) int {
	var projects stringSliceFlag
	fs := flag.NewFlagSet("run", flag.ContinueOnError)
	fs.Usage = func() {
		fmt.Fprintf(os.Stderr, `summarizer run — fetch + summarize one or more GitLab projects

Flags:
`)
		fs.PrintDefaults()
		fmt.Fprintf(os.Stderr, `
Config (YAML file, default ./summarizer.yaml) and CLI flags both contribute;
CLI wins. See examples/summarizer.yaml.

Env:
  GITLAB_TOKEN       required
  OPENAI_API_KEY     required when --provider openai (default); optional if --openai-base-url points at a local server
  OPENAI_BASE_URL    overrides the OpenAI-compatible endpoint (Ollama, vLLM, LM Studio)
  ANTHROPIC_API_KEY  required when --provider anthropic
`)
	}

	var (
		provider       = fs.String("provider", "", "LLM provider: openai or anthropic (default from config)")
		model          = fs.String("model", "", "LLM model id (default from config)")
		outputDir      = fs.String("output-dir", "", "output directory (default from config)")
		maxEvents      = fs.Int("max-events", 0, "hard cap on events sent to the LLM (default 200)")
		maxProjects    = fs.Int("max-projects", 0, "hard cap on projects fed to the LLM, applied after discovery and opt-out (default 50). Each project costs two completions, so this bounds the per-run bill. Dropped projects are listed on stderr.")
		dryRun         = fs.Bool("dry-run", false, "fetch GitLab data and print a summary; no LLM call, no file write")
		includeDiffs   = fs.Bool("include-diffs", false, "fetch per-MR diff text and feed it into the team prompt so the model can reason about code changes (default off; adds one API call per MR)")
		safetyURL      = fs.String("safety-url", "", "decision API base URL for prompt-injection guard (default from config safety.decision_url)")
		safetyToken    = fs.String("safety-token", "", "decision API token (default from $SAFETY_DECISION_TOKEN env or config). Prefer env var.")
		safetyEnabled  = fs.Bool("safety-enabled", false, "gate every LLM call through the prompt-injection detector; hard-fails the run on verdict (default off)")
		gitlabHost     = fs.String("gitlab-host", "", "GitLab base URL, e.g. https://gitlab.example.com (default from config)")
		gitlabToken    = fs.String("gitlab-token", "", "GitLab PRIVATE-TOKEN (default: $GITLAB_TOKEN). Prefer env var.")
		discoverGroups = stringSliceFlag{}
		internalOnly   = stringSliceFlag{}
		discoverTopic  = fs.Bool("discover-by-topic", false, "Scan every project on the GitLab instance carrying a summarize or summarize-team-only topic, across all groups the token can see. Same activity gate and audience policy as --discover-group; composes with it.")
		discoverActive = fs.Bool("discover-active", false, "Run every project the token can see that had activity in the window. This is the default when no other discovery input is given: active projects are included, they get a team-only report, and they opt out with a .summaryignore or .docignore file at the repo root. Customer-facing output still needs the summarize topic.")
		openaiKey      = fs.String("openai-key", "", "OpenAI API key (default: $OPENAI_API_KEY). Prefer env var. Optional when --openai-base-url is set to a non-default host (e.g. local Ollama/vLLM/LM Studio).")
		openaiBaseURL  = fs.String("openai-base-url", "", "OpenAI-compatible base URL (default $OPENAI_BASE_URL, then config openai_base_url, then https://api.openai.com/v1). Set to a local server for Ollama/vLLM/LM Studio.")
		anthropicKey   = fs.String("anthropic-key", "", "Anthropic API key (default: $ANTHROPIC_API_KEY). Prefer env var.")
		configPath     = fs.String("config", "./summarizer.yaml", "path to YAML config file")
	)
	fs.Var(&projects, "project", "GitLab project path (repeatable, or comma-separated). Examples: --project group/a --project group/b, or --project group/a,group/b. Composes with --discover-group; an explicit listing takes precedence on duplicate paths.")
	fs.Var(&discoverGroups, "discover-group", "GitLab group path to scan for active projects (repeatable, or comma-separated). Each project's MRs in the window are probed; active ones join the run alongside any --project listings. Recursion into subgroups is not implemented in v1 — pass the leaf group you want covered.")
	fs.Var(&internalOnly, "internal-only-project", "Project path whose customer-facing output is suppressed (repeatable, or comma-separated). Same effect as setting the summarize-team-only GitLab topic on the project. The three sources (this flag, the YAML internal_only_projects: block, the GitLab topic) union together.")
	if err := fs.Parse(args); err != nil {
		return exitUsage
	}

	// Default discovery is by activity: a project that was worked on
	// runs, without needing a topic or a config entry. Only when the
	// operator named some narrower input do we leave it alone.
	if len(projects) == 0 && len(discoverGroups) == 0 && !*discoverTopic && !*discoverActive {
		*discoverActive = true
		fmt.Fprintln(os.Stderr, "summarizer: no discovery input given, defaulting to --discover-active")
	}

	// Config: load YAML, then apply CLI overrides (CLI wins), then defaults.
	cfg, err := config.Load(*configPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "config error: %v\n", err)
		return exitConfig
	}
	if *gitlabHost != "" {
		cfg.GitLabHost = *gitlabHost
	}
	if *model != "" {
		cfg.Model = *model
	}
	if *openaiBaseURL != "" {
		cfg.OpenAIBaseURL = *openaiBaseURL
	} else if env := os.Getenv("OPENAI_BASE_URL"); env != "" {
		cfg.OpenAIBaseURL = env
	}
	if *outputDir != "" {
		cfg.OutputDir = *outputDir
	}
	if *maxEvents > 0 {
		cfg.MaxEvents = *maxEvents
	}
	if *provider != "" {
		cfg.Provider = *provider
	}
	cfg.Defaults()
	if err := cfg.Validate(); err != nil {
		fmt.Fprintf(os.Stderr, "config error: %v\n", err)
		return exitConfig
	}

	// Env fallback for secrets.
	gitlabTokenVal := *gitlabToken
	if gitlabTokenVal == "" {
		gitlabTokenVal = os.Getenv("GITLAB_TOKEN")
	}
	if gitlabTokenVal == "" {
		fmt.Fprintln(os.Stderr, "error: GitLab token not set (use --gitlab-token or GITLAB_TOKEN env)")
		return exitEnv
	}

	gc := gitlab.New(cfg.GitLabHost, gitlabTokenVal, 30*time.Second)

	// Resolve LLM provider and keys.
	llmProvider, code := resolveLLM(cfg, *openaiKey, *anthropicKey)
	if code != exitOK {
		return code
	}

	// Pick a publisher. Local disk by default; GitLab MR when
	// cfg.Publish.Enabled is true.
	pub, code := newPublisher(cfg)
	if code != exitOK {
		return code
	}

	// Safety guard. Disabled by default. When enabled, every LLM call
	// is preceded by a prompt-injection check via the decide API.
	guard, code := newGuard(cfg, *safetyEnabled, *safetyURL, *safetyToken)
	if code != exitOK {
		return code
	}

	// The report lands in a week-numbered directory, so the window is
	// that week. One window, no flag: an operator who wants something
	// else can post-date the cron line or read the branch by hand.
	//
	// Both come from one `now`. Computing the directory per publish
	// meant a run crossing Sunday midnight summarised week 43 and filed
	// it under 2026-W44.
	now := time.Now().UTC()
	weekStart := run.WeekStart(now)

	pipe := run.New(cfg, gc, llmProvider, pub, guard, run.Options{
		Projects:             projects,
		DiscoveredGroups:     discoverGroups,
		Since:                weekStart,
		Period:               run.WeekSlug(now),
		Provider:             cfg.Provider,
		Model:                cfg.Model,
		DryRun:               *dryRun,
		IncludeDiffs:         *includeDiffs,
		InternalOnlyProjects: unionSlices(internalOnly, cfg.InternalOnlyProjects),
		DiscoverByTopic:      *discoverTopic,
		DiscoverActive:       *discoverActive,
		MaxProjects:          *maxProjects,
		PublishTarget:        cfg.PublishTarget(),
	})

	sigCtx, stopSignals := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stopSignals()
	// A run-level deadline on top of the per-request one. Each HTTP
	// call is bounded at 60s and retried three times, so a hung
	// upstream makes one LLM call take ~4 minutes; 50 projects of two
	// calls each is a seven-hour worst case with nothing to stop it.
	//
	// Six hours is deliberately far above a real run — a capped 50-
	// project week takes minutes — so this only fires when something
	// is genuinely stuck. It corrupts nothing: Options.Period is
	// computed once at start-up, so a run that aborts late still files
	// under the week it started in, and every file it already wrote is
	// on the branch and listed by the summary.
	ctx, cancelRun := context.WithTimeout(sigCtx, runDeadline)
	defer cancelRun()

	res, err := pipe.Run(ctx)
	printSummary(res, err, *dryRun, weekStart)
	if err != nil {
		return classify(err)
	}
	return exitOK
}

func printSummary(res run.Result, err error, dryRun bool, weekStart time.Time) {
	// Print what was published whenever anything was, even when the run
	// ended in an error. A partial run that published 24 of 25 projects
	// is not a run that published nothing, and this summary line is what
	// a cron wrapper greps — hiding the successes behind an error made a
	// partial run indistinguishable from a total failure.
	// PartialFiles is in the gate as well as res.Projects: a run where
	// EVERY project published a file and then failed has no
	// res.Projects at all, and gating on that alone printed nothing —
	// the files were on the branch and nothing named them.
	if !dryRun && (err == nil || len(res.Projects) > 0 || len(res.PartialFiles) > 0) {
		if err != nil {
			fmt.Fprintf(os.Stderr, "summarizer: PARTIAL — %d project(s) published before the run failed; see the WARN lines above for the ones that did not\n", len(res.Projects))
			// Projects that published at least one file and then failed
			// are not in res.Projects, so the summary cannot count
			// them. Name them here or the operator has no way to learn
			// a report landed on the branch.
			for _, f := range res.PartialFiles {
				fmt.Fprintf(os.Stderr, "  → %s (project failed after this write)\n", f)
			}
		}
		var totalEvents, usedEvents int
		for _, p := range res.Projects {
			totalEvents += p.EventsFetched
			usedEvents += p.EventsUsed
		}
		// Count what was actually published, not what a full two-audience
		// run would produce: team-only projects write one file, the
		// epic rollups are separate, and a project that failed after a
		// write still produced a file. closedCount discounts every write
		// that landed on a branch whose MR is already merged — the
		// rollups included, which used to be reported as published.
		fileCount := len(res.RollupFiles) + len(res.EpicRollupFiles) + len(res.PartialFiles)
		closedCount := res.RollupFilesClosed
		for _, p := range res.Projects {
			fileCount += len(p.FilesWritten)
			closedCount += p.FilesClosed
		}
		// The elapsed hours matter more than the dates. A cron on
		// Monday produces a correct-looking two-day range covering three
		// hours of work; "167h elapsed" next to "3h elapsed" is what
		// makes the difference visible on the one line an operator
		// reads after a run.
		now := time.Now().UTC()
		// Re-running an already-published week writes to a branch whose MR
		// is already merged, so those files never reach the default branch.
		// Saying so here keeps "ok" honest: a run that published nothing to
		// main must not look like one that published everything.
		// "ok" on a failed run is the one word a cron wrapper greps for.
		// The PARTIAL line above says the run failed; printing "ok"
		// underneath it makes the same run match both patterns.
		verdict := "ok"
		if err != nil {
			verdict = "partial"
		}
		summary := fmt.Sprintf("summarizer: %s — %d project(s), %d event(s) (%d used), %d file(s) written",
			verdict, len(res.Projects), totalEvents, usedEvents, fileCount-closedCount)
		if closedCount > 0 {
			summary += fmt.Sprintf(" (%d already published this week)", closedCount)
		}
		fmt.Fprintf(os.Stderr, "%s (window=%s)\n",
			summary,
			fmt.Sprintf("this ISO week %s → %s (%s elapsed)",
				weekStart.Format("2006-01-02"), now.Format("2006-01-02 15:04"),
				now.Sub(weekStart).Truncate(time.Minute)))
		for _, p := range res.Projects {
			for _, f := range p.FilesWritten {
				fmt.Fprintf(os.Stderr, "  → %s\n", f)
			}
			for aud, u := range p.TokensByAudience {
				fmt.Fprintf(os.Stderr, "  tokens[%s/%s]: prompt=%d completion=%d total=%d\n",
					p.Project, aud, u.PromptTokens, u.CompletionTokens, u.TotalTokens)
			}
		}
		for _, f := range res.RollupFiles {
			fmt.Fprintf(os.Stderr, "  → %s (rollup)\n", f)
		}
		for _, f := range res.EpicRollupFiles {
			fmt.Fprintf(os.Stderr, "  → %s (epics rollup)\n", f)
		}
		for aud, u := range res.TokensByAudience {
			fmt.Fprintf(os.Stderr, "  tokens[rollup/%s]: prompt=%d completion=%d total=%d\n",
				aud, u.PromptTokens, u.CompletionTokens, u.TotalTokens)
		}
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "summarizer: %v\n", err)
	}
}

// classify maps pipeline errors to exit codes. Errors from internal/* packages
// are not necessarily wrapped with a recognizable error type yet, so this is
// a string-match pass. Tighten with typed sentinels if exit-code fidelity
// becomes important.
//
// Shared by `run` and `monthly`: both wrap their failures in the same few
// prefixes, so this is the single place deciding what a cron wrapper sees. A
// new error string that starts with none of them falls to exitUnknown — the
// honest answer, since we cannot tell which branch it belongs in — but the
// operator gets 1 instead of a useful code, so new errors should reuse a
// prefix rather than invent one.
func classify(err error) int {
	if err == nil {
		return exitOK
	}
	switch {
	case errors.Is(err, run.ErrInjection):
		return exitInjection
	}
	msg := err.Error()
	switch {
	// "llm " before "fetch ", deliberately. Both are substring matches
	// over the whole wrapped error, which includes the upstream
	// response body — and an OpenAI-compatible gateway (the README
	// supports Ollama, vLLM, LM Studio) returns bodies like
	// `{"error":"failed to fetch upstream model"}`. Checking "fetch "
	// first reported an LLM outage as a GitLab failure.
	//
	// The order is safe because a project path cannot contain a space,
	// so "llm " cannot appear in a GitLab-side message; the reverse is
	// not true.
	case strings.Contains(msg, "llm "):
		return exitLLM
	case strings.Contains(msg, "fetch "):
		return exitGitLab
	case strings.Contains(msg, "write "):
		return exitWrite
	// "want YYYY-MM" is parseMonth rejecting a --month flag value; it is
	// a malformed-input error, not a config-file one. Matched on the
	// tail rather than the whole string because %q renders the value.
	case strings.Contains(msg, "config"), strings.Contains(msg, "want YYYY-MM"):
		return exitConfig
	case strings.Contains(msg, "render"):
		return exitLLM
	}
	return exitUnknown
}

// unionSlices merges two string slices, deduping on exact equality.
// Order: first input first. Used to combine the --internal-only-project
// flag with summarizer.yaml's internal_only_projects block.
func unionSlices(a, b []string) []string {
	out := make([]string, 0, len(a)+len(b))
	seen := make(map[string]bool, len(a)+len(b))
	for _, s := range slices.Concat(a, b) {
		if !seen[s] {
			out = append(out, s)
			seen[s] = true
		}
	}
	return out
}

// stringSliceFlag is a custom flag.Value that accepts both repeated
// invocations (--project X --project Y) and comma-separated values
// (--project X,Y) in a single invocation. Empty entries are dropped so
// "--project X,,Y" doesn't produce an empty string.
//
// stdlib flag (as of Go 1.26) doesn't ship a slice type, and pulling in
// cobra for one flag is overkill. ~15 lines of custom code wins either way.
type stringSliceFlag []string

func (s *stringSliceFlag) String() string {
	return strings.Join(*s, ",")
}

func (s *stringSliceFlag) Set(v string) error {
	for _, p := range strings.Split(v, ",") {
		if p = strings.TrimSpace(p); p != "" {
			*s = append(*s, p)
		}
	}
	return nil
}
